import {
  forwardRef,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react"
import {
  motion,
  useMotionValue,
  useReducedMotion,
  useSpring,
  useTransform,
} from "motion/react"

import { playClickSound, playHoverSound } from "@/lib/sound"
import { cn } from "@/lib/utils"

export interface ScrollIndicatorSection {
  id: string
  title: ReactNode
  level?: number
  label?: string
  start?: number
  end?: number
  anchor?: number
  flightRange?: [number, number]
  subtitle?: string
  description?: string
  accent?: string
  meta?: string
  timestamp?: string
}

export interface ScrollIndicatorProps {
  /** Array of section items containing id and title */
  sections: ScrollIndicatorSection[]
  /** Controlled active section index */
  activeIndex?: number
  /** Callback triggered when the active section changes */
  onIndexChange?: (index: number) => void
  /** Optional custom scrollable container. If omitted, tracks window scroll */
  scrollRef?: React.RefObject<HTMLElement | null>
  /** Vertical offset in pixels when scrolling to a target section */
  scrollOffset?: number
  /** Total number of ticks along the ruler track (default: 60) */
  totalTicks?: number
  /** Additional CSS class names */
  className?: string
}

export const ScrollIndicator = forwardRef<HTMLDivElement, ScrollIndicatorProps>(
  function ScrollIndicatorComponent(
    {
      sections,
      activeIndex: controlledIndex,
      onIndexChange,
      scrollRef: externalScrollRef,
      scrollOffset = 64,
      totalTicks: totalTicksProp = 60,
      className,
    },
    ref
  ) {
    const containerRef = useRef<HTMLDivElement>(null)
    const trackRef = useRef<HTMLDivElement>(null)
    const [internalIndex, setInternalIndex] = useState(0)
    const [isHovered, setIsHovered] = useState(false)
    const [isOpen, setIsOpen] = useState(false)
    const reduceMotion = useReducedMotion()

    const activeIndex = controlledIndex ?? internalIndex

    // Lọc các section cấp 2 hoặc 3 nếu có phân cấp, ngược lại giữ nguyên
    const filteredSections = useMemo(() => {
      if (!sections.length) return []
      const hasHierarchicalLevels = sections.some(
        (s) => s.level === 2 || s.level === 3
      )
      return hasHierarchicalLevels
        ? sections.filter((s) => s.level === 2 || s.level === 3)
        : sections
    }, [sections])

    const totalTicks = Math.max(10, totalTicksProp)
    const lastTick = totalTicks - 1

    // Tiền tính toán danh sách ticks và vị trí % của từng section để tránh tính lại mỗi lần render
    const ticks = useMemo(
      () =>
        Array.from({ length: totalTicks }, (_, i) => ({
          index: i,
          pct: (i / lastTick) * 100,
          isMajor: i % 5 === 0,
        })),
      [totalTicks, lastTick]
    )

    const sectionMetrics = useMemo(() => {
      const denom = Math.max(filteredSections.length - 1, 1)
      return filteredSections.map((section, index) => {
        const tick = Math.round((index / denom) * lastTick)
        return {
          section,
          index,
          tick,
          pct: (tick / lastTick) * 100,
        }
      })
    }, [filteredSections, lastTick])

    const safeActiveIndex = Math.min(
      Math.max(0, activeIndex),
      Math.max(0, sectionMetrics.length - 1)
    )
    const activeTick = sectionMetrics[safeActiveIndex]?.tick ?? 0
    const activePct = sectionMetrics[safeActiveIndex]?.pct ?? 0

    // 1. Spring physics cho kim chỉ thị chính (mượt, đầm, không bị văng quá đà)
    const progressPct = useMotionValue(activePct)
    const smoothPct = useSpring(progressPct, {
      stiffness: reduceMotion ? 1000 : 380,
      damping: reduceMotion ? 100 : 34,
      mass: 0.65,
    })
    const activeLaserTop = useTransform(smoothPct, (v) => `${v}%`)

    // 2. Ghost Scrubber bám theo chuột trên thước (0 React re-render)
    const hoverPct = useMotionValue(activePct)
    const smoothHoverPct = useSpring(hoverPct, {
      stiffness: 550,
      damping: 40,
      mass: 0.4,
    })
    const ghostLaserTop = useTransform(smoothHoverPct, (v) => `${v}%`)

    useEffect(() => {
      progressPct.set(activePct)
    }, [activePct, progressPct])

    // Scroll Spy tối ưu bằng requestAnimationFrame chống Layout Thrashing
    useEffect(() => {
      if (controlledIndex !== undefined || sectionMetrics.length === 0) return

      const container = externalScrollRef?.current
      let rafId: number | null = null

      const resolveElement = (
        id: string,
        index: number
      ): HTMLElement | null => {
        if (container) {
          return (
            container.querySelector<HTMLElement>(
              `[data-section-index="${index}"]`
            ) || (id ? document.getElementById(id) : null)
          )
        }
        return (
          (id ? document.getElementById(id) : null) ||
          document.querySelector<HTMLElement>(`[data-section-index="${index}"]`)
        )
      }

      const updateActiveSection = () => {
        rafId = null

        const isAtBottom = container
          ? container.scrollTop + container.clientHeight >=
            container.scrollHeight - 48
          : typeof window !== "undefined" &&
            window.innerHeight + window.scrollY >=
              document.documentElement.scrollHeight - 48

        if (isAtBottom) {
          setInternalIndex((prev) =>
            prev !== sectionMetrics.length - 1
              ? sectionMetrics.length - 1
              : prev
          )
          return
        }

        const viewportThreshold =
          (container ? container.clientHeight : window.innerHeight) * 0.32
        const containerTop = container
          ? container.getBoundingClientRect().top
          : 0

        let nextActiveIdx = 0
        for (let i = 0; i < sectionMetrics.length; i++) {
          const el = resolveElement(sectionMetrics[i].section.id, i)
          if (!el) continue

          const top = el.getBoundingClientRect().top - containerTop
          if (top <= viewportThreshold) {
            nextActiveIdx = i
          } else {
            break
          }
        }

        setInternalIndex((prev) =>
          prev !== nextActiveIdx ? nextActiveIdx : prev
        )
      }

      const handleScroll = () => {
        if (rafId === null) {
          rafId = window.requestAnimationFrame(updateActiveSection)
        }
      }

      updateActiveSection()
      const scrollTarget: EventTarget = container ?? window
      scrollTarget.addEventListener("scroll", handleScroll, { passive: true })
      window.addEventListener("resize", handleScroll, { passive: true })

      return () => {
        if (rafId !== null) {
          window.cancelAnimationFrame(rafId)
        }
        scrollTarget.removeEventListener("scroll", handleScroll)
        window.removeEventListener("resize", handleScroll)
      }
    }, [controlledIndex, externalScrollRef, sectionMetrics])

    const scrollToSection = useCallback(
      (index: number) => {
        const container = externalScrollRef?.current
        const metric = sectionMetrics[index]
        if (!metric) return

        const { id } = metric.section

        if (container) {
          const sectionEl =
            container.querySelector<HTMLElement>(
              `[data-section-index="${index}"]`
            ) || (id ? document.getElementById(id) : null)

          if (sectionEl) {
            const top =
              sectionEl.getBoundingClientRect().top -
              container.getBoundingClientRect().top +
              container.scrollTop -
              scrollOffset
            container.scrollTo({
              top: Math.max(0, top),
              behavior: reduceMotion ? "auto" : "smooth",
            })
          }
        } else if (typeof window !== "undefined") {
          const sectionEl =
            (id ? document.getElementById(id) : null) ||
            document.querySelector<HTMLElement>(
              `[data-section-index="${index}"]`
            )

          if (sectionEl) {
            try {
              window.history.pushState(null, "", `#${id}`)
            } catch {
              // Bỏ qua lỗi history state trên môi trường sandboxed
            }

            const top =
              sectionEl.getBoundingClientRect().top +
              window.scrollY -
              scrollOffset
            window.scrollTo({
              top: Math.max(0, top),
              behavior: reduceMotion ? "auto" : "smooth",
            })
          }
        }
      },
      [externalScrollRef, reduceMotion, scrollOffset, sectionMetrics]
    )

    const handleClickSection = useCallback(
      (index: number) => {
        playClickSound()
        if (onIndexChange) {
          onIndexChange(index)
        } else {
          setInternalIndex(index)
        }
        scrollToSection(index)
        setIsOpen(false)
      },
      [onIndexChange, scrollToSection]
    )

    const handleTrackMouseMove = useCallback(
      (e: React.MouseEvent<HTMLDivElement>) => {
        if (!trackRef.current) return
        const rect = trackRef.current.getBoundingClientRect()
        if (rect.height <= 0) return
        const relY = Math.max(
          0,
          Math.min(1, (e.clientY - rect.top) / rect.height)
        )
        hoverPct.set(relY * 100)
      },
      [hoverPct]
    )

    const handleTrackClick = (e: React.MouseEvent<HTMLDivElement>) => {
      if ((e.target as HTMLElement).closest("button")) return

      playClickSound()
      setIsOpen((prev) => !prev)

      if (trackRef.current && sectionMetrics.length > 0) {
        const rect = trackRef.current.getBoundingClientRect()
        if (rect.height > 0) {
          const clickY = e.clientY - rect.top
          const progress = Math.max(0, Math.min(1, clickY / rect.height))
          const closestIdx = Math.round(progress * (sectionMetrics.length - 1))
          if (onIndexChange) {
            onIndexChange(closestIdx)
          } else {
            setInternalIndex(closestIdx)
          }
          scrollToSection(closestIdx)
        }
      }
    }

    // Đóng menu khi click ra ngoài hoặc nhấn phím Escape
    useEffect(() => {
      if (!isOpen) return

      const handlePointerDownOutside = (e: PointerEvent) => {
        if (
          containerRef.current &&
          !containerRef.current.contains(e.target as Node)
        ) {
          setIsOpen(false)
        }
      }

      const handleKeyDown = (e: KeyboardEvent) => {
        if (e.key === "Escape") {
          setIsOpen(false)
        }
      }

      window.addEventListener("pointerdown", handlePointerDownOutside)
      window.addEventListener("keydown", handleKeyDown)

      return () => {
        window.removeEventListener("pointerdown", handlePointerDownOutside)
        window.removeEventListener("keydown", handleKeyDown)
      }
    }, [isOpen])

    const isVisible = isOpen || isHovered

    return (
      <div
        ref={(node) => {
          containerRef.current = node
          if (typeof ref === "function") {
            ref(node)
          } else if (ref) {
            ref.current = node
          }
        }}
        className={cn("select-none", className)}
      >
        <div
          ref={trackRef}
          className="group relative flex h-full w-7 cursor-pointer justify-end sm:w-8"
          onMouseEnter={() => setIsHovered(true)}
          onMouseMove={handleTrackMouseMove}
          onMouseLeave={() => setIsHovered(false)}
          onClick={handleTrackClick}
          title={isOpen ? "Đóng danh sách mục" : "Nhấp vào để xem các mục"}
        >
          {/* Trục dọc mảnh tinh tế làm xương sống cho thước */}
          <div className="pointer-events-none absolute inset-y-0 right-0 w-px bg-border/40 transition-colors duration-300 group-hover:bg-border/70" />

          {/* 1. Các vạch chia thước tĩnh (Static Ruler Ticks) */}
          <div className="pointer-events-none absolute inset-0">
            {ticks.map(({ index, pct, isMajor }) => {
              const isPast = index <= activeTick

              return (
                <div
                  key={index}
                  className="absolute right-0 flex -translate-y-1/2 items-center justify-end"
                  style={{ top: `${pct}%` }}
                >
                  <div
                    className={cn(
                      "rounded-full transition-[width,background-color,opacity] duration-300 ease-out motion-reduce:transition-none",
                      isMajor
                        ? isPast
                          ? "h-[1.5px] w-3.5 bg-foreground/75 sm:w-4"
                          : "h-[1.5px] w-3 bg-foreground/30 sm:w-3.5"
                        : isPast
                          ? "h-px w-2 bg-foreground/45 sm:w-2.5"
                          : "h-px w-1.5 bg-muted-foreground/25 sm:w-2"
                    )}
                  />
                </div>
              )
            })}
          </div>

          {/* 2. Ghost Scrubber (Vạch dẫn đường mờ chạy theo trỏ chuột khi hover) */}
          <motion.div
            className={cn(
              "pointer-events-none absolute right-0 z-10 flex -translate-y-1/2 items-center justify-end transition-opacity duration-200",
              isHovered ? "opacity-100" : "opacity-0"
            )}
            style={{ top: ghostLaserTop }}
          >
            <div className="h-[1.5px] w-4 rounded-full bg-foreground/40 sm:w-5" />
          </motion.div>

          {/* 3. Đánh dấu vị trí các Section & Danh sách nút bấm */}
          <div className="pointer-events-none absolute inset-0">
            {sectionMetrics.map(({ section, index, pct }) => {
              const isActive = index === safeActiveIndex
              // Stagger nhẹ khi mở (tối đa 90ms) và đóng tức thì (0ms) để không bị trễ
              const staggerDelay =
                isVisible && !reduceMotion
                  ? `${Math.min(index * 16, 90)}ms`
                  : "0ms"

              return (
                <div key={section.id}>
                  {/* Điểm neo tĩnh của từng Section trên thước (Không nhân đôi màu primary) */}
                  <div
                    className={cn(
                      "pointer-events-none absolute right-0 -translate-y-1/2 rounded-full transition-all duration-300 ease-out",
                      isActive
                        ? "h-[2px] w-4 bg-primary/40 sm:w-5"
                        : "h-[1.5px] w-3.5 bg-foreground/55 sm:w-4"
                    )}
                    style={{ top: `${pct}%` }}
                  />

                  {/* Nút tiêu đề Section — Tách hẳn sang bên trái thước bằng right-full + pr-2.5 */}
                  <div
                    className={cn(
                      "absolute right-full z-30 flex -translate-y-1/2 items-center justify-end pr-2.5",
                      reduceMotion
                        ? ""
                        : "transition-[opacity,transform,filter] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)]",
                      isVisible
                        ? "blur-0 pointer-events-auto translate-x-0 scale-100 opacity-100"
                        : "pointer-events-none translate-x-2 scale-[0.97] opacity-0 blur-[1px]"
                    )}
                    style={{
                      top: `${pct}%`,
                      transitionDelay: staggerDelay,
                    }}
                  >
                    <button
                      type="button"
                      onMouseEnter={() => playHoverSound()}
                      onClick={(e) => {
                        e.stopPropagation()
                        handleClickSection(index)
                      }}
                      className={cn(
                        "group/btn relative flex cursor-pointer items-center gap-1.5 rounded-md border px-2.5 py-1 font-mono text-[11px] leading-none font-medium tracking-wider whitespace-nowrap uppercase backdrop-blur-md transition-all duration-150 motion-reduce:transition-none",
                        "focus-visible:ring-1 focus-visible:ring-primary focus-visible:ring-offset-1 focus-visible:ring-offset-background focus-visible:outline-none",
                        isActive
                          ? "border-primary/45 bg-background/95 font-semibold text-foreground shadow-[0_2px_10px_-2px_rgba(0,0,0,0.2)]"
                          : "border-border/60 bg-card/85 text-muted-foreground shadow-xs hover:-translate-x-0.5 hover:border-foreground/30 hover:bg-card/95 hover:text-foreground"
                      )}
                    >
                      {/* Chấm tròn trạng thái giúp phân biệt mục Active sang trọng, không làm nhoè chữ */}
                      <span
                        className={cn(
                          "h-1.5 w-1.5 shrink-0 rounded-full transition-all duration-200",
                          isActive
                            ? "scale-100 bg-primary shadow-[0_0_6px_var(--primary)]"
                            : "scale-75 bg-muted-foreground/35 group-hover/btn:scale-90 group-hover/btn:bg-foreground/60"
                        )}
                      />
                      <span>{section.title}</span>
                    </button>
                  </div>
                </div>
              )
            })}
          </div>

          {/* 4. Kim Laser Active duy nhất trượt bằng Spring */}
          <motion.div
            className="pointer-events-none absolute right-0 z-20 flex -translate-y-1/2 items-center justify-end"
            style={{ top: activeLaserTop }}
          >
            <div className="flex items-center">
              {/* Đầu kim phát sáng tinh tế */}
              <div className="h-1.5 w-1.5 rounded-full bg-primary shadow-[0_0_8px_1px_var(--primary)]" />
              {/* Thân kim gọn trong lòng thước (20px-24px), tuyệt đối không chạm vào vùng text */}
              <div className="-ml-0.5 h-[2px] w-4.5 rounded-r-full bg-primary shadow-[0_0_10px_var(--primary)] sm:w-5.5" />
            </div>
          </motion.div>
        </div>
      </div>
    )
  }
)

/**
 * Web Audio API synthesized audio utilities.
 * Generates lightweight, zero-latency micro-interaction sound effects using oscillators.
 */

const MUTE_KEY = "sound-muted"
const MUTE_EVENT = "sound-mute-change"

let muted = false
if (typeof window !== "undefined") {
  try {
    muted = localStorage.getItem(MUTE_KEY) === "1"
  } catch {
    // Ignore storage errors in private browsing or constrained environments
  }
}

export function isSoundMuted(): boolean {
  return muted
}

export function setSoundMuted(value: boolean): void {
  muted = value
  if (typeof window !== "undefined") {
    try {
      localStorage.setItem(MUTE_KEY, value ? "1" : "0")
    } catch {
      // Ignore storage errors
    }
    window.dispatchEvent(new CustomEvent(MUTE_EVENT))
  }
}

export function toggleSoundMuted(): boolean {
  setSoundMuted(!muted)
  return muted
}

export function subscribeSoundMuted(callback: () => void): () => void {
  if (typeof window === "undefined") return () => {}
  window.addEventListener(MUTE_EVENT, callback)
  const onStorage = (e: StorageEvent) => {
    if (e.key === MUTE_KEY) callback()
  }
  window.addEventListener("storage", onStorage)
  return () => {
    window.removeEventListener(MUTE_EVENT, callback)
    window.removeEventListener("storage", onStorage)
  }
}

let audioCtx: AudioContext | null = null

function initAudio(): AudioContext | null {
  if (typeof window === "undefined") return null
  if (!audioCtx) {
    const AudioContextClass =
      window.AudioContext ||
      (window as unknown as { webkitAudioContext?: typeof AudioContext })
        .webkitAudioContext
    if (AudioContextClass) {
      audioCtx = new AudioContextClass()
    }
  }
  if (audioCtx && audioCtx.state === "suspended") {
    audioCtx.resume().catch(() => {})
  }
  return audioCtx
}

if (typeof window !== "undefined") {
  const unlock = () => {
    initAudio()
    window.removeEventListener("pointerdown", unlock)
    window.removeEventListener("keydown", unlock)
    window.removeEventListener("touchstart", unlock)
  }
  window.addEventListener("pointerdown", unlock, { passive: true })
  window.addEventListener("keydown", unlock, { passive: true })
  window.addEventListener("touchstart", unlock, { passive: true })
}

export function getAudioContext(): AudioContext | null {
  return initAudio()
}

export function playHoverSound(volume = 0.08, pitch = 1.2): void {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = "sine"
    osc.frequency.setValueAtTime(1400 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(350 * pitch, now + 0.012)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.012)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.012)
  } catch {
    // AudioContext blocked or unsupported
  }
}

export function playClickSound(volume = 0.15, pitch = 1.0): void {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = "triangle"
    osc.frequency.setValueAtTime(850 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(160 * pitch, now + 0.02)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.02)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.02)
  } catch {
    // AudioContext blocked or unsupported
  }
}

export function playTickSound(volume = 0.08, pitch = 1.5): void {
  if (muted) return
  try {
    const ctx = getAudioContext()
    if (!ctx) return
    const now = ctx.currentTime

    const osc = ctx.createOscillator()
    const gain = ctx.createGain()

    osc.type = "sine"
    osc.frequency.setValueAtTime(1800 * pitch, now)
    osc.frequency.exponentialRampToValueAtTime(450 * pitch, now + 0.01)

    gain.gain.setValueAtTime(volume, now)
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.01)

    osc.connect(gain)
    gain.connect(ctx.destination)

    osc.start(now)
    osc.stop(now + 0.01)
  } catch {
    // AudioContext blocked or unsupported
  }
}
